<?php
require_once 'app_layout.php';
$role=current_role();$message='';$statuses=['Menunggu','Dalam Proses','Selesai','Sudah Diambil'];$from=$_GET['from']??'';$to=$_GET['to']??'';$date_pattern='/^\d{4}-\d{2}-\d{2}$/';if(!preg_match($date_pattern,$from))$from='';if(!preg_match($date_pattern,$to))$to='';
if($_SERVER['REQUEST_METHOD']==='POST'&&can_manage_transactions()){$id=(int)($_POST['id_transaksi']??0);$action=$_POST['action']??'';if($id>0&&$action==='update'){$status=$_POST['status_cucian']??'';if(in_array($status,$statuses,true)){$stmt=mysqli_prepare($koneksi,'UPDATE transaksi SET status_cucian=? WHERE id_transaksi=?');mysqli_stmt_bind_param($stmt,'si',$status,$id);mysqli_stmt_execute($stmt);$message='Status transaksi diperbarui.';}}elseif($id>0&&$action==='delete'){mysqli_begin_transaction($koneksi);$stmt=mysqli_prepare($koneksi,'DELETE FROM detail_transaksi WHERE id_transaksi=?');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$stmt=mysqli_prepare($koneksi,'DELETE FROM transaksi WHERE id_transaksi=?');mysqli_stmt_bind_param($stmt,'i',$id);$ok=mysqli_stmt_execute($stmt);$ok?mysqli_commit($koneksi):mysqli_rollback($koneksi);$message=$ok?'Transaksi dihapus.':'Transaksi gagal dihapus.';}}
$conditions=[];$params=[];$types='';if($role==='User'){$conditions[]='t.id_karyawan=?';$params[]=(int)$_SESSION['user_id'];$types.='i';}if($from!==''){$conditions[]='DATE(t.tanggal_transaksi)>=?';$params[]=$from;$types.='s';}if($to!==''){$conditions[]='DATE(t.tanggal_transaksi)<=?';$params[]=$to;$types.='s';}$sql='SELECT t.id_transaksi,t.kode_transaksi,t.tanggal_transaksi,t.total_harga,t.status_pembayaran,t.status_cucian,p.nama AS nama_pelanggan,p.no_hp FROM transaksi t LEFT JOIN pelanggan p ON p.id_pelanggan=t.id_pelanggan';if($conditions)$sql.=' WHERE '.implode(' AND ',$conditions);$sql.=' ORDER BY t.tanggal_transaksi DESC';$stmt=mysqli_prepare($koneksi,$sql);if($params)mysqli_stmt_bind_param($stmt,$types,...$params);mysqli_stmt_execute($stmt);$rows=mysqli_stmt_get_result($stmt);app_start('History Transaksi','history');
?>
<div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm font-bold uppercase tracking-widest text-cyan-700">Login sebagai <?= e($role); ?></p><h1 class="mt-2 text-3xl font-black">History transaksi</h1><p class="muted mt-2 text-sm">Cari transaksi berdasarkan tanggal transaksi.</p></div><a href="transaksi_baru.php" class="rounded-lg bg-cyan-500 px-4 py-3 text-sm font-black text-slate-950">+ Transaksi Baru</a></div><form method="GET" class="mt-6 grid gap-3 rounded-2xl bg-white p-5 shadow-sm sm:grid-cols-[1fr_1fr_auto_auto]"><div><label class="mb-1 block text-xs font-bold uppercase text-slate-500">Dari tanggal</label><input type="date" name="from" value="<?= e($from); ?>" class="w-full rounded-lg border border-slate-200 px-3 py-2"></div><div><label class="mb-1 block text-xs font-bold uppercase text-slate-500">Sampai tanggal</label><input type="date" name="to" value="<?= e($to); ?>" class="w-full rounded-lg border border-slate-200 px-3 py-2"></div><button class="rounded-lg bg-indigo-700 px-4 py-2 text-sm font-bold text-white">Filter</button><a href="history_transaksi.php" class="rounded-lg border border-slate-300 px-4 py-2 text-center text-sm font-bold text-slate-600">Reset</a></form><?php if($message): ?><div class="mt-5 rounded-lg bg-emerald-100 p-3 text-sm font-bold text-emerald-700"><?= e($message); ?></div><?php endif; ?><div class="mt-6 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="min-w-[900px] w-full text-left text-sm"><thead class="bg-slate-900 text-xs uppercase tracking-wider text-white"><tr><th class="px-5 py-4">Kode</th><th class="px-5 py-4">Pelanggan</th><th class="px-5 py-4">Tanggal</th><th class="px-5 py-4">Total</th><th class="px-5 py-4">Pembayaran</th><th class="px-5 py-4">Status</th><th class="px-5 py-4">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><?php while($row=mysqli_fetch_assoc($rows)): ?><tr><td class="px-5 py-4 font-bold"><?= e($row['kode_transaksi']); ?></td><td class="px-5 py-4"><?= e($row['nama_pelanggan']??'-'); ?><br><span class="text-xs text-slate-400"><?= e($row['no_hp']??''); ?></span></td><td class="whitespace-nowrap px-5 py-4"><?= date('d/m/Y H:i',strtotime($row['tanggal_transaksi'])); ?></td><td class="whitespace-nowrap px-5 py-4 font-bold">Rp <?= number_format($row['total_harga'],0,',','.'); ?></td><td class="px-5 py-4"><?= e($row['status_pembayaran']); ?></td><td class="px-5 py-4"><span class="rounded-full bg-cyan-50 px-3 py-1 text-xs font-bold text-cyan-700"><?= e($row['status_cucian']); ?></span></td><td class="px-5 py-4"><div class="flex items-center gap-2"><a href="nota.php?id=<?= (int)$row['id_transaksi']; ?>" class="rounded-md border px-2 py-1 text-xs font-bold">Nota</a><?php if(can_manage_transactions()): ?><form method="POST" class="flex items-center gap-1"><input type="hidden" name="action" value="update"><input type="hidden" name="id_transaksi" value="<?= (int)$row['id_transaksi']; ?>"><select name="status_cucian" class="rounded-md border px-2 py-1 text-xs"><?php foreach($statuses as $status): ?><option <?= $status===$row['status_cucian']?'selected':''; ?>><?= e($status); ?></option><?php endforeach; ?></select><button class="rounded-md bg-indigo-600 px-2 py-1 text-xs font-bold text-white">Simpan</button></form><form method="POST" onsubmit="return confirm('Hapus transaksi ini?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_transaksi" value="<?= (int)$row['id_transaksi']; ?>"><button class="rounded-md bg-rose-600 px-2 py-1 text-xs font-bold text-white">Hapus</button></form><?php endif; ?></div></td></tr><?php endwhile; ?></tbody></table></div>
<?php app_end(); ?>
